        <Panel><div className="flex flex-wrap items-end gap-3"><form className="flex flex-wrap items-end gap-2" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const type = String(form.get("type")); const options = ["SELECT","STATUS","MULTI_SELECT"].includes(type) ? { values: String(form.get("options")).split(",").map((s) => s.trim()).filter(Boolean) } : type === "RELATION" ? { targetDatabaseId: String(form.get("targetDatabaseId")), multiple: true } : {}; void mutate(() => request(`/api/dashboard/workspace/databases/${selectedDatabase.id}/properties`, { method: "POST", body: JSON.stringify({ name: form.get("name"), type, options, sortOrder: selectedDatabase.properties.length }) }), "Property added."); event.currentTarget.reset(); }}><Field label="Property" name="name" required placeholder="Category"/><Select label="Type" name="type"><option>TEXT</option><option>NUMBER</option><option>CHECKBOX</option><option>DATE</option><option>SELECT</option><option>MULTI_SELECT</option><option>URL</option><option>STATUS</option><option>RELATION</option></Select><Field label="Options (comma separated)" name="options" placeholder="For select/status"/><Select label="Relation target database" name="targetDatabaseId"><option value="">Choose if relation</option>{databases.filter((database) => database.id !== selectedDatabase.id && !database.archivedAt).map((database) => <option key={database.id} value={database.id}>{database.name}</option>)}</Select><Button><Plus size={14}/>Add field</Button></form></div></Panel>
