        {activeView?.type === "BOARD" && boardProperty && <div className="grid gap-3 overflow-x-auto pb-2 sm:grid-cols-2 xl:grid-cols-3">{(((boardProperty.options.values as string[] | undefined) ?? [])).map((group) => <section key={group} className="min-h-40 rounded-2xl border border-white/10 bg-black/10 p-3"><h3 className="mb-3 text-xs font-semibold uppercase tracking-wide text-white/55">{group}</h3><div className="grid gap-2">{records.filter((record) => (record.data as Json)?.[boardProperty.name] === group).map((record) => <div key={record.id} className="rounded-xl border border-white/10 bg-white/[.04] p-3"><p className="text-sm font-medium">{String((record.data as Json)?.Name ?? record.id)}</p><RecordEditor key={`${record.id}:${record.revision}`} properties={selectedDatabase.properties} record={record} relationChoices={relationChoices} onSave={(payload) => void mutate(() => request(`/api/dashboard/workspace/databases/${selectedDatabase.id}/records/${record.id}`, { method: "PATCH", body: JSON.stringify(payload) }), "Record saved.")}/></div>)}</div></section>)}</div>}
